import{_ as e,c as i,o as s,a2 as r}from"./chunks/framework.CIiVzG-O.js";const h=JSON.parse('{"title":"Instalación","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/installation.md","filePath":"es/guide/installation.md","lastUpdated":1793163976000}'),o={name:"es/guide/installation.md"};function t(l,a,n,c,d,p){return s(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h1><p>NueZip está disponible para macOS a través de la Mac App Store.</p><h2 id="opciones-de-descarga" tabindex="-1">Opciones de descarga <a class="header-anchor" href="#opciones-de-descarga" aria-label="Permalink to &quot;Opciones de descarga&quot;">​</a></h2><h3 id="mac-app-store-recomendado" tabindex="-1">Mac App Store (recomendado) <a class="header-anchor" href="#mac-app-store-recomendado" aria-label="Permalink to &quot;Mac App Store (recomendado)&quot;">​</a></h3><ul><li><strong>Descargar</strong>: <a href="https://apps.apple.com/app/id6785846417" target="_blank" rel="noreferrer">NueZip en la Mac App Store</a></li></ul><p>La versión de la Mac App Store ofrece actualizaciones automáticas e integración perfecta con macOS.</p><h3 id="github-releases-alternativa" tabindex="-1">GitHub Releases (alternativa) <a class="header-anchor" href="#github-releases-alternativa" aria-label="Permalink to &quot;GitHub Releases (alternativa)&quot;">​</a></h3><p>Si prefieres descargar directamente, puedes obtener la app desde <a href="https://github.com/nuezip/nuezip/releases" target="_blank" rel="noreferrer">GitHub Releases</a>. Ten en cuenta que esta versión no recibe actualizaciones automáticas.</p><h2 id="pasos-de-instalacion" tabindex="-1">Pasos de instalación <a class="header-anchor" href="#pasos-de-instalacion" aria-label="Permalink to &quot;Pasos de instalación&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>Haz clic en el enlace de descarga de arriba o busca &quot;NueZip&quot; en la Mac App Store</li><li>Haz clic en &quot;Obtener&quot; para descargar la app</li><li>La app se descargará e instalará automáticamente</li><li>Abre NueZip desde tu carpeta de Aplicaciones o el Launchpad</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>Descarga el último <code>.dmg</code> desde la página de Releases</li><li>Haz doble clic en el <code>.dmg</code> descargado para abrirlo</li><li>Arrastra el icono de <code>NueZip.app</code> a tu carpeta de <code>Aplicaciones</code></li><li>Expulsa la imagen montada y abre <code>NueZip</code> desde <code>Aplicaciones</code></li></ol><p>Si macOS impide abrir la app (Gatekeeper), abre <strong>Configuración del sistema → Privacidad y seguridad</strong> y haz clic en <strong>Abrir de todos modos</strong> para NueZip, o haz clic derecho en la app y elige <strong>Abrir</strong>.</p><h2 id="primer-inicio" tabindex="-1">Primer inicio <a class="header-anchor" href="#primer-inicio" aria-label="Permalink to &quot;Primer inicio&quot;">​</a></h2><p>Cuando abres NueZip por primera vez, se te guiará a través de un flujo de incorporación para:</p><ul><li><strong>Conceder acceso a carpetas</strong>: Permite que NueZip acceda a directorios comunes (Descargas, Documentos, Escritorio)</li><li><strong>Habilitar la extensión de Finder</strong>: Activa el menú contextual con clic derecho para operaciones rápidas con archivos</li></ul><p>Concede los permisos cuando se te soliciten. Puedes modificarlos en cualquier momento en <strong>Configuración del sistema → Privacidad y seguridad</strong>.</p><h2 id="actualizaciones" tabindex="-1">Actualizaciones <a class="header-anchor" href="#actualizaciones" aria-label="Permalink to &quot;Actualizaciones&quot;">​</a></h2><ul><li><strong>Versión de la Mac App Store</strong>: Las actualizaciones las gestiona automáticamente la App Store</li><li><strong>Versión de GitHub Releases</strong>: Descarga la versión más reciente y reemplaza la app en <code>Aplicaciones</code></li></ul><h2 id="desinstalacion" tabindex="-1">Desinstalación <a class="header-anchor" href="#desinstalacion" aria-label="Permalink to &quot;Desinstalación&quot;">​</a></h2><p>Para desinstalar NueZip:</p><ol><li>Cierra NueZip</li><li>Arrastra <code>NueZip.app</code> desde <code>Aplicaciones</code> a la Papelera</li><li>(Opcional) Elimina los datos y registros de la app:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Logs/nuezip</span></span></code></pre></div><h2 id="requisitos-del-sistema" tabindex="-1">Requisitos del sistema <a class="header-anchor" href="#requisitos-del-sistema" aria-label="Permalink to &quot;Requisitos del sistema&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma (14) o posterior recomendado</li><li><strong>CPU</strong>: Apple Silicon (serie M) o Intel (64 bits)</li><li><strong>Memoria</strong>: 4 GB mínimo, 8 GB recomendado</li><li><strong>Almacenamiento</strong>: ~50 MB</li></ul><h2 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h2><p>Si encuentras problemas durante la instalación:</p><ul><li><strong>macOS bloquea la app</strong>: Abre <strong>Configuración del sistema → Privacidad y seguridad</strong> y haz clic en <strong>Abrir de todos modos</strong> para NueZip</li><li><strong>Advertencia de notarización</strong>: Descarga una compilación firmada y notarizada desde la Mac App Store</li></ul><p>Para obtener más ayuda, visita la <a href="./troubleshooting.html">guía de solución de problemas</a>.</p>`,30)])])}const m=e(o,[["render",t]]);export{h as __pageData,m as default};
